class Solution {
  public int maximumGain(String s, int x, int y) {
    int[] score = {0};
    if (x >= y) {
      String rest = removePairs(s, 'a', 'b', x, score);
      removePairs(rest, 'b', 'a', y, score);
    } else {
      String rest = removePairs(s, 'b', 'a', y, score);
      removePairs(rest, 'a', 'b', x, score);
    }
    return score[0];
  }

  private String removePairs(String s, char first, char second, int value, int[] score) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c == second && stack.length() > 0 && stack.charAt(stack.length() - 1) == first) {
        stack.deleteCharAt(stack.length() - 1);
        score[0] += value;
      } else stack.append(c);
    }
    return stack.toString();
  }
}
